SELECT O997019.COGESTAO, O997019.COGESTAOCONTAB, O997019.COUGCONTAB, O997019.COUG, ( SUM(DECODE(( SUBSTR(O997019.COCONTACONTABIL,1,1) ),1,( DECODE(O997019.INDEBITOCREDITO,'D',O997019.VALANCAMENTO,'C',-O997019.VALANCAMENTO) ),0)) )+( SUM(DECODE(( SUBSTR(O997019.COCONTACONTABIL,1,1) ),2,( DECODE(O997019.INDEBITOCREDITO,'D',O997019.VALANCAMENTO,'C',-O997019.VALANCAMENTO) ),0)) )+( SUM(DECODE(( SUBSTR(O997019.COCONTACONTABIL,1,1) ),3,( DECODE(O997019.INDEBITOCREDITO,'D',O997019.VALANCAMENTO,'C',-O997019.VALANCAMENTO) ),0)) )+( SUM(DECODE(( SUBSTR(O997019.COCONTACONTABIL,1,1) ),4,( DECODE(O997019.INDEBITOCREDITO,'D',O997019.VALANCAMENTO,'C',-O997019.VALANCAMENTO) ),0)) ), SUM(DECODE(( SUBSTR(O997019.COCONTACONTABIL,1,1) ),4,( DECODE(O997019.INDEBITOCREDITO,'D',O997019.VALANCAMENTO,'C',-O997019.VALANCAMENTO) ),0)), SUM(DECODE(( SUBSTR(O997019.COCONTACONTABIL,1,1) ),3,( DECODE(O997019.INDEBITOCREDITO,'D',O997019.VALANCAMENTO,'C',-O997019.VALANCAMENTO) ),0)), SUM(DECODE(( SUBSTR(O997019.COCONTACONTABIL,1,1) ),2,( DECODE(O997019.INDEBITOCREDITO,'D',O997019.VALANCAMENTO,'C',-O997019.VALANCAMENTO) ),0)), SUM(DECODE(( SUBSTR(O997019.COCONTACONTABIL,1,1) ),1,( DECODE(O997019.INDEBITOCREDITO,'D',O997019.VALANCAMENTO,'C',-O997019.VALANCAMENTO) ),0))
FROM MIL2026.LANCAMENTOCONTABIL O997019
WHERE ( O997019.COCONTACONTABIL BETWEEN 100000000 AND 499999999 )
GROUP BY O997019.COGESTAO, O997019.COGESTAOCONTAB, O997019.COUGCONTAB, O997019.COUG
;

